    maj_b, min_b, pat_b, pre_b, is_pre_b = parse(b)

    # Compare major, minor, patch numerically
    if maj_a != maj_b:
        return -1 if maj_a < maj_b else 1
    if min_a != min_b:
        return -1 if min_a < min_b else 1
    if pat_a != pat_b:
        return -1 if pat_a < pat_b else 1

    # Compare pre-release existence
    # Pre-release versions have lower precedence than normal versions
    if is_pre_a and not is_pre_b:
        return -1
    if not is_pre_a and is_pre_b:
        return 1
    if not is_pre_a and not is_pre_b:
