    min_len = min(len(a_ids), len(b_ids))
    for i in range(min_len):
        id_a = a_ids[i]
        id_b = b_ids[i]

        is_num_a = id_a.isdigit()
        is_num_b = id_b.isdigit()

        if is_num_a and is_num_b:
            val_a = int(id_a)
            val_b = int(id_b)
            if val_a < val_b:
                return -1
            elif val_a > val_b:
                return 1
        elif is_num_a and not is_num_b:
            # Numeric identifiers have lower precedence than alphanumeric
            return -1
        elif not is_num_a and is_num_b:
            return 1
        else:
            # Both are alphanumeric, compare lexically (ASCII order)
            if id_a < id_b:
                return -1
            elif id_a > id_b:
                return 1

    # If all compared identifiers are equal, the longer set has higher precedence
    if len(a_ids) < len(b_ids):
        return -1
    elif len(a_ids) > len(b_ids):
        return 1
    else:
        return 0
